function meta(id, started) {
  return {
    conversationId: id,
    started,
    callId: `call-${id.slice(2)}`,
    agentId: 'agent-aerolabs-01',
    office: 'Agentic Office',
  }
}

function session({ audio, tools, transfer = '' }) {
  return {
    audio,
    participants: ['Customer', 'This agent'],
    tools,
    transfer,
  }
}

function successFlow(skill, action) {
  return {
    status: 'Run finished · contained',
    meta: '4 steps · 0 failed',
    nodes: [
      { id: 'msg', label: 'Customer message', kind: 'start', x: 48, y: 36 },
      { id: 'skill', label: skill, kind: 'skill', x: 48, y: 148 },
      { id: 'tool', label: action, kind: 'tool', x: 48, y: 260 },
      { id: 'end', label: 'Agent reply', kind: 'end', x: 48, y: 372 },
    ],
    edges: [
      ['msg', 'skill'],
      ['skill', 'tool'],
      ['tool', 'end'],
    ],
    failPath: [],
  }
}

