function clockLabel(seconds) {
  const whole = Math.max(0, Math.floor(seconds))
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, '0')}`
}

function containedRecord(spec) {
  const events = spec.turns.map((turn, index) => {
    const tool = turn.kind === 'action' || turn.kind === 'skill' || turn.kind === 'fail'
    return {
      id: `${spec.id}-${index}`,
      kind: turn.kind,
      label: turn.label,
      summary: turn.summary,
      t: turn.t,
      w: tool ? 1 : 5,
      meta: tool ? (turn.meta || '240ms') : '5s',
      ...(tool ? { ok: turn.kind !== 'fail' } : {}),
      input: turn.input || (turn.text ? [{ k: 'Said', v: turn.text }] : []),
      output: turn.output || [],
    }
  })
  const speakerName = { customer: 'Customer', agent: 'Agent', system: 'System' }
  return {
    id: spec.id,
    date: spec.date,
    time: spec.time,
    title: spec.title,
    summary: spec.summary,
    extendedSummary: spec.extendedSummary,
    channel: spec.channel,
    entry: spec.entry,
    outcome: spec.outcome,
    aiCsat: spec.aiCsat,
    skills: spec.skills,
    failedSkills: spec.failedSkills || [],
    handleTime: spec.handleTime,
    escalationReason: spec.escalationReason || '',
    actionItems: spec.actionItems,
    purposes: spec.purposes,
    topics: spec.topics,
    moments: spec.moments,
    transcript: spec.turns.filter((turn) => speakerName[turn.who]).map((turn) => ({
      time: clockLabel(turn.t),
      speaker: speakerName[turn.who],
      text: turn.text,
    })),
    logs: spec.logs.map((row) => ({
      time: clockLabel(row.t),
      level: 'Info',
      source: 'Agent',
      message: row.message,
    })),
    session: session({ audio: spec.audio, tools: spec.tools, transfer: spec.transfer || '' }),
    metadata: meta(spec.id, spec.started),
    traces: {
      resolution: spec.resolution,
      resolutionSub: spec.resolutionSub,
      skills: events.filter((event) => event.kind === 'skill').length,
      actions: events.filter((event) => event.kind === 'action').length,
      failedActions: events.filter((event) => event.kind === 'fail').length,
      audio: spec.traceAudio,
      audioSub: spec.audioSub,
      duration: spec.duration,
      silence: [],
      events,
    },
    flow: spec.flow,
  }
}

const line = (who, t, text, label, summary) => ({ who, kind: who, t, text, label, summary })
const tool = (t, label, summary, input, output) => ({
  who: 'system',
  kind: 'action',
  t,
  text: summary,
  label,
  summary,
  input,
  output,
})

